      back.forEach(input=>{input.oninput=()=>{mode='custom';modeButtons.forEach(button=>button.classList.remove('active'));recalc('back')}});
      modeButtons.forEach(button=>{button.onclick=()=>{mode=button.dataset.closeMode;modeButtons.forEach(other=>other.classList.toggle('active',other===button));if(mode==='keep')back.forEach(input=>{input.value=0});recalc('mode')}});
      recalc('init');
