        const backLines=items.map((item,index)=>({sku:item.sku,quantity:Number(back[index].value)||0})).filter(line=>line.quantity>0);
        if(!soldLines.length&&!backLines.length)return W.toast('Nada que cerrar','Indica lo vendido o lo que regresa a bodega.','warning');
        if(Number(values.amountReceived)>total)return W.toast('El pago supera el total','','warning');
        const result=await W.command('closure.create',{localId:local.id,sold:soldLines,returned:backLines,paymentMethod:values.paymentMethod,amountReceived:values.amountReceived},{success:'Cierre registrado'});
        if(!result)return;
